

# Diffie-Hellman Key Exchange with MITM Attack


p, g = 23, 5


# Private keys
a, b = 6, 15


# Public keys
A = pow(g, a, p)
B = pow(g, b, p)


print("--- Normal Diffie-Hellman ---")
print("Alice Public Key:", A)
print("Bob Public Key:", B)


# Shared secret keys
KA = pow(B, a, p)
KB = pow(A, b, p)


print("Alice Shared Key:", KA)
print("Bob Shared Key:", KB)
print("Keys Match:", KA == KB)


# MITM Attack by Eve
print("\n--- MITM Attack ---")


e1, e2 = 7, 9


# Eve sends fake public keys
fake_A = pow(g, e1, p)
fake_B = pow(g, e2, p)


# Keys generated by Alice, Bob and Eve
alice_key = pow(fake_B, a, p)
bob_key = pow(fake_A, b, p)


eve_alice = pow(A, e2, p)
eve_bob = pow(B, e1, p)


print("Alice-Eve Key:", alice_key)
print("Eve-Alice Key:", eve_alice)
print("Bob-Eve Key:", bob_key)
print("Eve-Bob Key:", eve_bob)


print("Eve can communicate with Alice:", alice_key == eve_alice)
print("Eve can communicate with Bob:", bob_key == eve_bob)
print("Alice and Bob have same key:", alice_key == bob_key)




